import random

class Weapon:
    def __init__(self, damage, range, critical_chance):
        self.damage = damage
        self.range = range
        self.critical_chance = critical_chance

    def attack(self, target):
        attack_range = random.randint(1, self.range)
        attack_strength = self.damage * random.expovariate(1 / self.critical_chance)
        return min(self.range + attack_range, attack_strength) - 1

class RPG:
    def __init__(self, player, target):
        self.player = player
        self.target = target
        self.weapons = [Weapon(random.randint(1, 100), random.randint(1, 50), random.randint(1, 10)) for _ in range(5)]

    def play(self):
        print(f"Welcome, {self.player}! You are about to assassinate {self.target}'s identity.")
        for weapon in self.weapons:
            print(f"Choose a weapon: {weapon.name} ({weapon.damage}, {weapon.range}, {weapon.critical_chance})")
            choice = int(input("Enter your choice (1-5): "))
            if choice == 1:
                self.player.use(weapon.attack(self.target))
            elif choice == 2:
                self.target.use(weapon.attack(self.player))
            elif choice == 3:
                self.player.use(weapon.attack(self.target, range=weapon.range))
            elif choice == 4:
                self.target.use(weapon.attack(self.player, range=weapon.range))
            elif choice == 5:
                self.player.use(weapon.attack(self.target, critical_chance=weapon.critical_chance))
            else:
                print("Invalid choice. Please enter a number from 1 to 5.")

# Example usage
player = RPG("Player 1", "High-Profile Individual")
player.play()
